class Items {
public:
	struct BagItemInfo {
		std::string name = "";
		uint16_t id = 0;
		double chance = 0;
		uint32_t minAmount = 1;
		uint32_t maxAmount = 1;
		std::string monsterClass = "";
		uint32_t monsterRaceId = 0;
		bool bossOnly = false;
	};

	struct SurpriseBagDrop {
		uint16_t itemId = 0;
		uint16_t count = 0;
	};

	using NameMap = std::unordered_multimap<std::string, uint16_t>;
	using InventoryVector = std::vector<uint16_t>;

	Items();

	// non-copyable
	Items(const Items &) = delete;
	Items &operator=(const Items &) = delete;

	bool reload();
	void clear();

	void loadFromProtobuf();

	const ItemType &operator[](size_t id) const {
		return getItemType(id);
	}
	const ItemType &getItemType(size_t id) const;
	ItemType &getItemType(size_t id);

	/**
	 * @brief Check if the itemid "hasId" is stored on "items", if not, return false
	 *
	 * @param hasId check item id
	 * @return true if the item exist
	 * @return false if the item not exist
	 */
	bool hasItemType(size_t hasId) const;

	uint16_t getItemIdByName(const std::string &name);

	ItemTypes_t getLootType(const std::string &strValue) const;

	bool loadFromXml();
	void parseItemNode(const pugi::xml_node &itemNode, uint16_t id);

	void buildInventoryList();
	const InventoryVector &getInventory() const {
		return inventory;
	}

	size_t size() const {
		return items.size();
	}

	std::vector<ItemType> &getItems() {
		return items;
	}

	NameMap nameToItems;

	void addLadderId(uint16_t newId) {
		ladders.push_back(newId);
	}
	void addDummyId(uint16_t newId, uint16_t rate) {
		dummys[newId] = rate;
	}

	const std::vector<uint16_t> &getLadders() const {
		return ladders;
	}
	const std::unordered_map<uint16_t, uint16_t> &getDummys() const {
		return dummys;
	}

	static std::string getAugmentNameByType(Augment_t augmentType);

	static bool isAugmentWithoutValueDescription(Augment_t augmentType) {
		static std::vector<Augment_t> vector = {
			Augment_t::IncreasedDamage,
			Augment_t::PowerfulImpact,
			Augment_t::StrongImpact,
		};

		return std::ranges::find(vector, augmentType) != vector.end();
	}

	std::vector<const BagItemInfo*> getAllBagItems() const {
		std::vector<const BagItemInfo*> allBagItems;
		for (const auto &entry : bagItems) {
			allBagItems.push_back(&(entry.second));
		}
		return allBagItems;
	}

	void setItemBag(uint16_t itemId, const std::string &itemName, double chance, uint32_t minAmount, uint32_t maxAmount, const std::string &monsterClass, uint32_t monsterRaceId, bool bossOnly);
	std::vector<SurpriseBagDrop> rollSurpriseBagLoot(const std::shared_ptr<MonsterType> &monsterType) const;

private:
	std::vector<ItemType> items;
	std::vector<uint16_t> ladders;
	std::unordered_map<uint16_t, uint16_t> dummys;
	InventoryVector inventory;
	std::unordered_map<int32_t, BagItemInfo> bagItems;
};

