			}

			if (it.abilities->conditionSuppressions[CONDITION_DRUNK] != 0) {
				ss.str("");
				ss << "Hard Drinking";
				descriptions.emplace_back("Skill Boost", ss.str());
			}

			if (it.abilities->invisible) {
				ss.str("");
