Weapons &Weapons::getInstance() {
	return inject<Weapons>();
}

namespace {
	// Map the weapon attack effect (CONST_ME_*_ATTACK 304-309) to the client's CreatureMark
	// weaponType (1-6). The client jump-table is NOT contiguous: sword 304->1, club 305->2,
	// axe 306->3, fist 309->4, monk staff 307->5, monk daggers 308->6.
	uint8_t markWeaponType(uint16_t attackEffect) {
		switch (attackEffect) {
			case CONST_ME_SWORD_ATTACK:
				return 1;
			case CONST_ME_CLUB_ATTACK:
				return 2;
			case CONST_ME_AXE_ATTACK:
				return 3;
			case CONST_ME_FIST_ATTACK:
				return 4;
			case CONST_ME_MONK_STAFF_ATTACK:
				return 5;
			case CONST_ME_MONK_DAGGERS_ATTACK:
				return 6;
			default:
				return 0;
		}
	}
} // namespace

WeaponShared_ptr Weapons::getWeapon(const std::shared_ptr<Item> &item) const {
	if (!item) {
		return nullptr;
	}

	const auto it = weapons.find(item->getID());
	if (it == weapons.end()) {
		return nullptr;
	}
	return it->second;
}

void Weapons::clear(bool isFromXML /*= false*/) {
	if (isFromXML) {
		int numRemoved = 0;
		for (auto it = weapons.begin(); it != weapons.end();) {
			if (it->second && it->second->isFromXML()) {
				g_logger().debug("Weapon with id '{}' is from XML and will be removed.", it->first);
				it = weapons.erase(it);
				++numRemoved;
			} else {
				++it;
			}
		}

		if (numRemoved > 0) {
			g_logger().debug("Removed '{}' Weapon from XML.", numRemoved);
		}

		return;
	}

	weapons.clear();
}

bool Weapons::registerLuaEvent(const WeaponShared_ptr &event, bool fromXML /*= false*/) {
	weapons[event->getID()] = event;
	if (fromXML) {
		event->setFromXML(fromXML);
	}
	return true;
}

// Monsters
int32_t Weapons::getMaxMeleeDamage(int32_t attackSkill, int32_t attackValue) {
	// Returns maximum melee attack damage, rounding up
	return static_cast<int32_t>(std::ceil((attackSkill * (attackValue * 0.05)) + (attackValue * 0.5)));
}

// Players
int32_t Weapons::getMaxWeaponDamage(uint32_t level, int32_t attackSkill, int32_t attackValue, float attackFactor, bool isMelee) {
	if (isMelee) {
		return attackValue > 0 ? static_cast<int32_t>(std::round((0.085 * attackFactor * attackValue * attackSkill) + (level / 5))) : 0;
	} else {
		return static_cast<int32_t>(std::round((0.09 * attackFactor * attackValue * attackSkill) + (level / 5)));
	}
}

