	return source;
}

std::string toCamelCase(const std::string &str) {
	std::string result;
	bool capitalizeNext = false;

	for (const char ch : str) {
		if (ch == '_' || std::isspace(ch) || ch == '-') {
			capitalizeNext = true;
		} else {
			if (capitalizeNext) {
				result += std::toupper(ch);
				capitalizeNext = false;
			} else {
				result += std::tolower(ch);
			}
		}
	}

	return result;
}

std::string toPascalCase(const std::string &str) {
	std::string result;
	bool capitalizeNext = true;

	for (const char ch : str) {
		if (ch == '_' || std::isspace(ch) || ch == '-') {
			capitalizeNext = true;
		} else {
			if (capitalizeNext) {
				result += std::toupper(ch);
				capitalizeNext = false;
			} else {
				result += ch; // Keep the character as is.
			}
		}
	}

	return result;
}

std::string toSnakeCase(const std::string &str) {
	std::string result;
	for (const char ch : str) {
		if (std::isupper(ch)) {
			result += '_';
			result += std::tolower(ch);
		} else if (std::isspace(ch) || ch == '-') {
			result += '_';
		} else {
			result += ch;
		}
	}

	return result;
}

std::string toKebabCase(const std::string &str) {
	std::string result;
	for (const char ch : str) {
		if (std::isupper(ch)) {
			result += '-';
			result += std::tolower(ch);
		} else if (std::isspace(ch) || ch == '_') {
			result += '-';
		} else {
			result += ch;
		}
	}

	return result;
}

std::string toStartCaseWithSpace(const std::string &str) {
	std::string result;
	for (size_t i = 0; i < str.length(); ++i) {
		const char ch = str[i];
		if (i == 0 || std::isupper(ch)) {
			if (i > 0) {
				result += ' ';
			}
			result += std::toupper(ch);
		} else {
			result += std::tolower(ch);
		}
	}
	return result;
}

StringVector explodeString(const std::string &inString, const std::string &separator, int32_t limit /* = -1*/) {
	StringVector returnVector;
	std::string::size_type start = 0, end = 0;

	while (--limit != -1 && (end = inString.find(separator, start)) != std::string::npos) {
		returnVector.push_back(inString.substr(start, end - start));
		start = end + separator.size();
	}

	returnVector.push_back(inString.substr(start));
	return returnVector;
}

IntegerVector vectorAtoi(const StringVector &stringVector) {
	IntegerVector returnVector;
	for (const auto &string : stringVector) {
		returnVector.push_back(std::stoi(string));
	}
	return returnVector;
}

std::mt19937 &getRandomGenerator() {
	static std::random_device rd;
	static std::mt19937 generator(rd());
	return generator;
}

int32_t getBaseDamageHealing(uint32_t level) {
	const auto step = static_cast<int32_t>(std::floor((std::sqrt(2.0 * static_cast<double>(level) + 2025.0) + 5.0) / 10.0));
	return static_cast<int32_t>(std::floor(static_cast<double>(level + 1000) / step)) + 50 * step - 450;
}

int32_t uniform_random(int32_t minNumber, int32_t maxNumber) {
	static std::uniform_int_distribution<int32_t> uniformRand;
	if (minNumber == maxNumber) {
		return minNumber;
	}
	if (minNumber > maxNumber) {
		std::swap(minNumber, maxNumber);
	}
	return uniformRand(getRandomGenerator(), std::uniform_int_distribution<int32_t>::param_type(minNumber, maxNumber));
}

int32_t normal_random(int32_t minNumber, int32_t maxNumber) {
	static std::normal_distribution<float> normalRand(0.5f, 0.25f);
	float v;
	do {
		v = normalRand(getRandomGenerator());
	} while (v < 0.0 || v > 1.0);

	auto &&[a, b] = std::minmax(minNumber, maxNumber);
	return a + std::lround(v * (b - a));
}

bool boolean_random(double probability /* = 0.5*/) {
	static std::bernoulli_distribution booleanRand;
	return booleanRand(getRandomGenerator(), std::bernoulli_distribution::param_type(probability));
}

void trimString(std::string &str) {
	str.erase(str.find_last_not_of(' ') + 1);
	str.erase(0, str.find_first_not_of(' '));
}

std::string convertIPToString(uint32_t ip) {
	std::array<char, 16> buffer;
	auto result = fmt::format_to_n(buffer.data(), buffer.size() - 1, "{}.{}.{}.{}", ip & 0xFF, (ip >> 8) & 0xFF, (ip >> 16) & 0xFF, (ip >> 24));

	buffer[std::min(result.size, buffer.size() - 1)] = '\0';

	return std::string(buffer.data());
}

namespace {
	std::string formatTimeString(time_t time, const char* format) {
		std::tm tm_buf {};
#if defined(_WIN32) || defined(_WIN64)
		localtime_s(&tm_buf, &time);
#else
		localtime_r(&time, &tm_buf);
#endif
		char buffer[32];
		if (std::strftime(buffer, sizeof(buffer), format, &tm_buf) != 0) {
			return buffer;
		}
		return {};
	}
} // namespace

std::string formatDate(time_t time) {
	return formatTimeString(time, "%d/%m/%Y %H:%M:%S");
}

std::string formatDateShort(time_t time) {
	return formatTimeString(time, "%Y-%m-%d %X");
}

std::string formatTime(time_t time) {
