		actionTaskEvent = 0;
	}

	if (!inEventMovePush && !g_configManager().getBoolean(PUSH_WHEN_ATTACKING)) {
		cancelPush();
	}

	if (task) {
		actionTaskEvent = g_dispatcher().scheduleEvent(task);
		if (resetIdleTime) {
			this->resetIdleTime();
		}
	}
}

