void Player::addOutfit(uint16_t lookType, uint8_t addons) {
	for (auto &outfitEntry : outfitsMap) {
		if (outfitEntry.lookType == lookType) {
			setOutfitsModified(true);
			outfitEntry.addons |= addons;
			return;
		}
	}

	setOutfitsModified(true);
	outfitsMap.emplace_back(lookType, addons);

	if (const auto &outfit = Outfits::getInstance().getOutfitByLookType(getPlayer(), lookType)) {
		sendScreenshotAndBannerUnlockedCosmetic(outfit->name, lookType, std::clamp<uint8_t>(addons, 0, 2));
	}
}

bool Player::removeOutfit(uint16_t lookType) {
	for (auto it = outfitsMap.begin(), end = outfitsMap.end(); it != end; ++it) {
		const auto &entry = *it;
		if (entry.lookType == lookType) {
			outfitsMap.erase(it);
			setOutfitsModified(true);
			return true;
		}
	}
	return false;
}

bool Player::removeOutfitAddon(uint16_t lookType, uint8_t addons) {
	for (auto &outfitEntry : outfitsMap) {
		if (outfitEntry.lookType == lookType) {
			outfitEntry.addons &= ~addons;
			setOutfitsModified(true);
			return true;
		}
	}
	return false;
}

bool Player::getOutfitAddons(const std::shared_ptr<Outfit> &outfit, uint8_t &addons) const {
	if (group->access || g_configManager().getBoolean(UNLOCK_ALL_OUTFITS)) {
		addons = 3;
		return true;
	}

	if (outfit->premium && !isPremium()) {
		return false;
	}

	for (const auto &outfitEntry : outfitsMap) {
		if (outfitEntry.lookType != outfit->lookType) {
			continue;
		}

		addons = outfitEntry.addons;
		return true;
	}

	if (!outfit->unlocked) {
		return false;
	}

	addons = 0;
	return true;
}

bool Player::canFamiliar(uint16_t lookType) const {
	if (group->access) {
		return true;
	}

	const auto &familiar = Familiars::getInstance().getFamiliarByLookType(getVocationId(), lookType);
	if (!familiar) {
		return false;
	}

	bool fullUnlock = g_configManager().getBoolean(UNLOCK_ALL_FAMILIARS);

	if (familiar->premium && !isPremium() && !fullUnlock) {
		return false;
	}

	if (fullUnlock) {
		return true;
	}

	if (familiar->unlocked) {
		return true;
	}

	if (std::ranges::any_of(familiars, [&](const FamiliarEntry &familiarEntry) {
			return familiarEntry.lookType == lookType;
		})) {
		return true;
	}

	return false;
}

void Player::addFamiliar(uint16_t lookType) {
	if (std::ranges::none_of(familiars, [&](const FamiliarEntry &familiarEntry) {
			return familiarEntry.lookType == lookType;
		})) {
		familiars.emplace_back(lookType);
	}
}

bool Player::removeFamiliar(uint16_t lookType) {
	const auto initialSize = familiars.size();
	std::erase_if(familiars, [lookType](const FamiliarEntry &entry) {
		return entry.lookType == lookType;
	});
	return familiars.size() != initialSize;
}

bool Player::getFamiliar(const std::shared_ptr<Familiar> &familiar) const {
	if (group->access) {
		return true;
	}

	if (familiar->premium && !isPremium()) {
		return false;
	}

	if (std::ranges::any_of(familiars, [&](const FamiliarEntry &familiarEntry) {
			return familiarEntry.lookType == familiar->lookType;
		})) {
		return true;
	}

	if (!familiar->unlocked) {
		return false;
	}

