uint32_t Player::getAttackSpeed() const {
	int32_t modifiers = 0;

	if (mountAttributes) {
		const auto &mount = g_game().mounts->getMountByClientID(defaultOutfit.lookMount);
		if (isMounted() && mount) {
			if (mount->attackSpeed > 0) {
				if (mount->attackSpeed >= vocation->getAttackSpeed()) {
					modifiers = 0;
				} else {
					modifiers += mount->attackSpeed;
				}
			}
		}
	}

	if (outfitAttributes) {
		const auto &outfit = Outfits::getInstance().getOutfitByLookType(getPlayer(), defaultOutfit.lookType);
		if (outfit) {
			if (outfit->attackSpeed > 0) {
				if (outfit->attackSpeed >= vocation->getAttackSpeed()) {
					modifiers = 0;
				} else {
					modifiers += outfit->attackSpeed;
				}
			}
		}
	}

	uint32_t attackSpeed = vocation->getAttackSpeed() - modifiers;
	return attackSpeed;
}

double Player::getLostPercent() const {
	int32_t blessingCount = 0;
	const uint8_t maxBlessing = (operatingSystem == CLIENTOS_NEW_WINDOWS || operatingSystem == CLIENTOS_NEW_MAC) ? 8 : 6;
	for (int i = 2; i <= maxBlessing; i++) {
		if (hasBlessing(i)) {
			blessingCount++;
		}
	}

	int32_t deathLosePercent = g_configManager().getNumber(DEATH_LOSE_PERCENT);
	if (deathLosePercent != -1) {
		if (isPromoted()) {
			deathLosePercent -= 3;
		}

		deathLosePercent -= blessingCount;
		return std::max<int32_t>(0, deathLosePercent) / 100.;
	}

	bool isRetro = g_game().isRetroPVP();
	const auto factor = (isRetro ? 6.31 : 8);
	double percentReduction = (blessingCount * factor) / 100.;

	double lossPercent;
	if (level >= 24) {
		const double tmpLevel = level + (levelPercent / 100.);
		lossPercent = ((tmpLevel + 50) * 50 * ((tmpLevel * tmpLevel) - (5 * tmpLevel) + 8)) / experience;
	} else {
		percentReduction = (percentReduction >= 0.40 ? 0.50 : percentReduction);
		lossPercent = 10;
	}

	g_logger().debug("[{}] - lossPercent {}", __FUNCTION__, lossPercent);
	g_logger().debug("[{}] - before promotion {}", __FUNCTION__, percentReduction);

	if (isPromoted()) {
		percentReduction += 30 / 100.;
		g_logger().debug("[{}] - after promotion {}", __FUNCTION__, percentReduction);
	}

	g_logger().debug("[{}] - total lost percent {}", __FUNCTION__, lossPercent - (lossPercent * percentReduction));

	return lossPercent - (lossPercent * percentReduction);
}

