BlockType_t Player::blockHit(const std::shared_ptr<Creature> &attacker, const CombatType_t &combatType, int32_t &damage, bool checkDefense, bool checkArmor, bool field) {
	BlockType_t blockType = Creature::blockHit(attacker, combatType, damage, checkDefense, checkArmor, field);
	if (attacker) {
		sendCreatureSquare(attacker, SQ_COLOR_BLACK);
	}

	if (blockType != BLOCK_NONE) {
		return blockType;
	}

	if (damage > 0) {
		for (int32_t slot = CONST_SLOT_FIRST; slot <= CONST_SLOT_LAST; ++slot) {
			if (!isItemAbilityEnabled(static_cast<Slots_t>(slot))) {
				continue;
			}

			const auto &item = inventory[slot];
			if (!item) {
				continue;
			}

			for (uint8_t slotid = 0; slotid < item->getImbuementSlot(); slotid++) {
				ImbuementInfo imbuementInfo;
				if (!item->getImbuementInfo(slotid, &imbuementInfo)) {
					continue;
				}

				const int16_t &imbuementAbsorbPercent = imbuementInfo.imbuement->absorbPercent[combatTypeToIndex(combatType)];

				if (imbuementAbsorbPercent != 0) {
					damage -= std::ceil(damage * (imbuementAbsorbPercent / 100.));
				}
			}

			// Absorb Percent
			const ItemType &it = Item::items[item->getID()];
			if (it.abilities) {
				int totalAbsorbPercent = 0;
				const int16_t &absorbPercent = it.abilities->absorbPercent[combatTypeToIndex(combatType)];
				if (absorbPercent != 0) {
					totalAbsorbPercent += absorbPercent;
				}

				const int16_t mantraAbsorbValue = it.abilities->mantraAbsorbValue[combatTypeToIndex(combatType)];
				if (mantraAbsorbValue != 0) {
					const int16_t mantraAbsorbPercent = getMantraAbsorbPercent(mantraAbsorbValue);
					if (mantraAbsorbPercent != 0) {
						totalAbsorbPercent += mantraAbsorbPercent;
					}
				}

				if (field) {
					const int16_t &fieldAbsorbPercent = it.abilities->fieldAbsorbPercent[combatTypeToIndex(combatType)];
					if (fieldAbsorbPercent != 0) {
						totalAbsorbPercent += fieldAbsorbPercent;
					}
				}

				if (totalAbsorbPercent != 0) {
					damage -= std::round(damage * (totalAbsorbPercent / 100.0));

					const auto charges = item->getAttribute<uint16_t>(ItemAttribute_t::CHARGES);
					if (charges != 0) {
						g_game().transformItem(item, item->getID(), charges - 1);
					}
				}
			}
		}

		// Vocation absorb
		if (vocation->getAbsorbPercent(combatType) > 0) {
			damage -= static_cast<int32_t>(std::ceil((double)(damage * vocation->getAbsorbPercent(combatType))) / 100.);
		}

		// Wheel of destiny - apply resistance
		wheel()->adjustDamageBasedOnResistanceAndSkill(damage, combatType);

		if (damage <= 0) {
			damage = 0;
			blockType = BLOCK_ARMOR;
		}
	}

	return blockType;
}

void Player::doAttacking(uint32_t interval) {
	if (lastAttack == 0) {
		lastAttack = OTSYS_TIME() - getAttackSpeed() - 1;
	}

	if (hasCondition(CONDITION_PACIFIED)) {
		return;
	}

	const auto &attackedCreature = getAttackedCreature();
	if (!attackedCreature) {
		return;
	}

	if ((OTSYS_TIME() - lastAttack) >= getAttackSpeed()) {
		bool result = false;

		const auto &tool = getWeapon();
		const auto &weapon = g_weapons().getWeapon(tool);
		uint32_t delay = getAttackSpeed();
		bool classicSpeed = g_configManager().getBoolean(CLASSIC_ATTACK_SPEED);

		if (weapon) {
			if (!weapon->interruptSwing()) {
				result = weapon->useWeapon(static_self_cast<Player>(), tool, attackedCreature);
			} else if (!classicSpeed && !canDoAction()) {
				delay = getNextActionTime();
			} else {
				result = weapon->useWeapon(static_self_cast<Player>(), tool, attackedCreature);
			}
		} else if (hasWeaponDistanceEquipped()) {
			return;
		} else {
			result = Weapon::useFist(static_self_cast<Player>(), attackedCreature);
		}

		const auto &task = createPlayerTask(
			std::max<uint32_t>(SCHEDULER_MINTICKS, delay),
			[playerId = getID()] { g_game().checkCreatureAttack(playerId); },
			__FUNCTION__
		);

		if (!classicSpeed) {
			setNextActionTask(task, false);
		} else {
			g_dispatcher().scheduleEvent(task);
		}

		if (result) {
			updateLastAggressiveAction();
			updateLastAttack();
		}
	}
}

void Player::death(const std::shared_ptr<Creature> &lastHitCreature) {
	if (!g_configManager().getBoolean(TOGGLE_MOUNT_IN_PZ) && isMounted()) {
		dismount();
		g_game().internalCreatureChangeOutfit(getPlayer(), defaultOutfit);
	}

	loginPosition = town->getTemplePosition();

	g_game().sendSingleSoundEffect(static_self_cast<Player>()->getPosition(), sex == PLAYERSEX_FEMALE ? SoundEffect_t::HUMAN_FEMALE_DEATH : SoundEffect_t::HUMAN_MALE_DEATH, getPlayer());
	if (skillLoss) {
		int playerDmg = 0;
		int othersDmg = 0;
		uint32_t opponents = 0;
		uint32_t inFightTicks = g_configManager().getNumber(FAIRFIGHT_TIMERANGE);
		for (const auto &[creatureId, damageInfo] : damageMap) {
			const auto &[total, ticks] = damageInfo;
			if ((OTSYS_TIME() - ticks) <= inFightTicks) {
				const auto &damageDealer = g_game().getPlayerByID(creatureId);
				if (damageDealer) {
					playerDmg += total;
					opponents += damageDealer->getLevel();
				} else {
					othersDmg += total;
				}
			}
		}

		bool pvpDeath = false;
		if (playerDmg > 0 || othersDmg > 0) {
			pvpDeath = (Player::lastHitIsPlayer(lastHitCreature) || playerDmg / (playerDmg + static_cast<double>(othersDmg)) >= 0.05);
		}

		uint8_t unfairFightReduction = 100;
		if (pvpDeath && opponents > level) {
			double reduce = level / static_cast<double>(opponents);
			unfairFightReduction = std::max<uint8_t>(20, std::floor((reduce * 100) + 0.5));
		}

		// Magic level loss
		uint64_t sumMana = 0;
		uint64_t lostMana = 0;

		// Sum up all the mana
		for (uint32_t i = 1; i <= magLevel; ++i) {
			sumMana += vocation->getReqMana(i);
		}

		sumMana += manaSpent;

		double deathLossPercent = getLostPercent() * (unfairFightReduction / 100.);

		// Charm bless bestiary
		const auto charmBlessRaceId = getRaceIdByCharmsArray(CHARM_MINOR_BLESS);
		if (lastHitCreature && lastHitCreature->getMonster() && charmBlessRaceId != 0) {
			const auto &mType = g_monsters().getMonsterType(lastHitCreature->getName());
			if (mType && mType->info.raceid == charmBlessRaceId) {
				if (const auto &charmBless = g_iobestiary().getBestiaryCharm(CHARM_MINOR_BLESS)) {
					const auto charmTier = getTierByCharmsArray(CHARM_MINOR_BLESS);
					const auto percentReduction = charmBless->chance[charmTier] / 100;
					deathLossPercent -= deathLossPercent * percentReduction;
				}
			}
		}

		double magicLossPercent = deathLossPercent / 100.;
		if (g_configManager().getBoolean(HALF_LOSS_MAGIC) && magicLossPercent > 0) {
			magicLossPercent /= 2;
		}

		lostMana = static_cast<uint64_t>(sumMana * magicLossPercent);

		while (lostMana > manaSpent && magLevel > 0) {
			lostMana -= manaSpent;
			manaSpent = vocation->getReqMana(magLevel);
			magLevel--;
		}

		manaSpent = (lostMana > manaSpent) ? 0 : manaSpent - lostMana;

		uint64_t nextReqMana = vocation->getReqMana(magLevel + 1);
		if (nextReqMana > vocation->getReqMana(magLevel)) {
			magLevelPercent = Player::getPercentLevel(manaSpent, nextReqMana);
		} else {
			magLevelPercent = 0;
		}

		// Level loss
		double expLossPercent = deathLossPercent / 100.;
		if (g_configManager().getBoolean(HALF_LOSS_EXP) && expLossPercent > 0) {
			expLossPercent /= 2;
		}

		auto expLoss = static_cast<uint64_t>(std::ceil((experience * expLossPercent)));
		g_logger().debug("[{}] - experience lost {}", __FUNCTION__, expLoss);

		g_events().eventPlayerOnLoseExperience(static_self_cast<Player>(), expLoss);
		g_callbacks().executeCallback(EventCallback_t::playerOnLoseExperience, &EventCallback::playerOnLoseExperience, getPlayer(), expLoss);

		sendTextMessage(MESSAGE_EVENT_ADVANCE, "You are dead.");
		std::ostringstream lostExp;
		lostExp << "You lost " << expLoss << " experience.";

		// Skill loss
		for (uint8_t i = SKILL_FIRST; i <= SKILL_LAST; ++i) { // For each skill
			uint64_t sumSkillTries = 0;
			for (uint16_t c = 11; c <= skills[i].level; ++c) { // Sum up all required tries for all skill levels
				sumSkillTries += vocation->getReqSkillTries(i, c);
			}

			sumSkillTries += skills[i].tries;

			double skillLossPercent = deathLossPercent / 100.;
			if (g_configManager().getBoolean(HALF_LOSS_SKILL) && skillLossPercent > 0) {
				skillLossPercent /= 2;
			}

			auto lostSkillTries = static_cast<uint32_t>(sumSkillTries * skillLossPercent);
			while (lostSkillTries > skills[i].tries) {
				lostSkillTries -= skills[i].tries;

				if (skills[i].level <= 10) {
					skills[i].level = 10;
					skills[i].tries = 0;
					lostSkillTries = 0;
					break;
				}

				skills[i].tries = vocation->getReqSkillTries(i, skills[i].level);
				skills[i].level--;
			}

			skills[i].tries = (lostSkillTries > skills[i].tries) ? 0 : skills[i].tries - lostSkillTries;
			skills[i].percent = Player::getPercentLevel(skills[i].tries, vocation->getReqSkillTries(i, skills[i].level));
		}

		sendTextMessage(MESSAGE_EVENT_ADVANCE, lostExp.str());

		if (expLoss != 0) {
			uint32_t oldLevel = level;

			if (vocation->getId() == VOCATION_NONE || level > 7) {
				experience -= expLoss;
			}

			while (level > 1 && experience < Player::getExpForLevel(level)) {
				--level;
				healthMax = std::max<int32_t>(0, healthMax - vocation->getHPGain());
				manaMax = std::max<int32_t>(0, manaMax - vocation->getManaGain());
				capacity = std::max<int32_t>(0, capacity - vocation->getCapGain());
			}

			if (oldLevel != level) {
				if (level < oldLevel && g_configManager().getBoolean(TOGGLE_WHEELSYSTEM)) {
					wheel()->reclaimExcessPoints();
				}

				std::ostringstream ss;
				ss << "You were downgraded from Level " << oldLevel << " to Level " << level << '.';
				sendTextMessage(MESSAGE_EVENT_ADVANCE, ss.str());
			}

			uint64_t currLevelExp = Player::getExpForLevel(level);
			uint64_t nextLevelExp = Player::getExpForLevel(level + 1);
			if (nextLevelExp > currLevelExp) {
				levelPercent = Player::getPercentLevel(experience - currLevelExp, nextLevelExp - currLevelExp);
			} else {
				levelPercent = 0;
			}
		}

		std::ostringstream deathType;
		deathType << "You died during ";
		if (pvpDeath) {
			deathType << "PvP.";
		} else {
			deathType << "PvE.";
		}
		sendTextMessage(MESSAGE_EVENT_ADVANCE, deathType.str());

		auto adventurerBlessingLevel = g_configManager().getNumber(ADVENTURERSBLESSING_LEVEL);
		auto willNotLoseBless = getLevel() < adventurerBlessingLevel && getVocationId() > VOCATION_NONE;

		std::string bless = getBlessingsName();
		std::ostringstream blessOutput;
		if (willNotLoseBless) {
			blessOutput << fmt::format("You still have adventurer's blessings for being level lower than {}!", adventurerBlessingLevel);
		} else {
			bless.empty() ? blessOutput << "You weren't protected with any blessings."
						  : blessOutput << "You were blessed with " << bless;

			const auto playerSkull = getSkull();
			bool hasSkull = (playerSkull == Skulls_t::SKULL_RED || playerSkull == Skulls_t::SKULL_BLACK);
			const auto &amulet = getInventoryItem(CONST_SLOT_NECKLACE);
			const bool usingAol = amulet && amulet->getID() == ITEM_AMULETOFLOSS;
			const bool twistProtectsAol = !hasSkull && pvpDeath && hasBlessing(1);
			bool consumedBlessingProtection = false;
			uint8_t maxBlessing = 8;
			if (twistProtectsAol) {
				consumedBlessingProtection = true;
				auto storeCount = getBlessingCount(1, true);
				if (storeCount > 0) {
					auto currentStore = kv()->scoped("summary")->scoped("blessings")->scoped(fmt::format("{}", 1))->get("amount");
					if (currentStore) {
						auto newAmount = std::max(0, static_cast<int>(currentStore->getNumber()) - 1);
						kv()->scoped("summary")->scoped("blessings")->scoped(fmt::format("{}", 1))->set("amount", newAmount);
					}
				} else {
					removeBlessing(1, 1);
				}
			} else {
				for (int i = 2; i <= maxBlessing; i++) {
					auto storeCount = getBlessingCount(i, true);
					if (storeCount > 0) {
						consumedBlessingProtection = true;
						auto currentStore = kv()->scoped("summary")->scoped("blessings")->scoped(fmt::format("{}", i))->get("amount");
						if (currentStore) {
							auto newAmount = std::max(0, static_cast<int>(currentStore->getNumber()) - 1);
							kv()->scoped("summary")->scoped("blessings")->scoped(fmt::format("{}", i))->set("amount", newAmount);
						}
					} else if (hasBlessing(i)) {
						consumedBlessingProtection = true;
						removeBlessing(i, 1);
					}
				}
			}

			if (usingAol && !consumedBlessingProtection) {
				g_game().internalRemoveItem(amulet);
			}
		}
		sendTextMessage(MESSAGE_EVENT_ADVANCE, blessOutput.str());

		sendStats();
		sendSkills();
		sendReLoginWindow(unfairFightReduction);
		sendBlessStatus();
		lastLogout = getTimeNow();
		if (getSkull() == SKULL_BLACK) {
			health = g_configManager().getNumber(BLACK_SKULL_DEATH_HEALTH);
			mana = g_configManager().getNumber(BLACK_SKULL_DEATH_MANA);
		} else {
			health = healthMax;
			mana = manaMax;
		}

		auto it = conditions.begin(), end = conditions.end();
		while (it != end) {
			auto condition = *it;
			// isSupress block to delete spells conditions (ensures that the player cannot, for example, reset the cooldown time of the familiar and summon several)
			if (condition->isPersistent() && condition->isRemovableOnDeath()) {
				it = conditions.erase(it);

				condition->endCondition(static_self_cast<Player>());
				onEndCondition(condition->getType());
			} else {
				++it;
			}
		}
		despawn();
	} else {
		setSkillLoss(true);

		auto it = conditions.begin(), end = conditions.end();
		while (it != end) {
			auto condition = *it;
			if (condition->isPersistent()) {
				it = conditions.erase(it);

				condition->endCondition(static_self_cast<Player>());
				onEndCondition(condition->getType());
			} else {
				++it;
			}
		}

		health = healthMax;
		g_game().internalTeleport(static_self_cast<Player>(), getTemplePosition(), true);
		g_game().addCreatureHealth(static_self_cast<Player>());
		g_game().addPlayerMana(static_self_cast<Player>());
		onThink(EVENT_CREATURE_THINK_INTERVAL);
		onIdleStatus();
		sendStats();
	}
}

bool Player::spawn() {
	setDead(false);

	const Position &pos = getLoginPosition();

	if (!g_game().map.placeCreature(pos, getPlayer(), false, true)) {
		return false;
	}

	const auto &spectators = Spectators().find<Creature>(position, true);
	for (const auto &spectator : spectators) {
		if (const auto &tmpPlayer = spectator->getPlayer()) {
			tmpPlayer->sendCreatureAppear(static_self_cast<Player>(), pos, true);
		}

		spectator->onCreatureAppear(static_self_cast<Player>(), false);
	}

	// notify status change when login after dead
	for (const auto &[key, player] : g_game().getPlayers()) {
		if (!this->isInGhostMode() || player->isAccessPlayer()) {
			VipStatus_t status = player->isExerciseTraining() ? VipStatus_t::TRAINING : VipStatus_t::ONLINE;
			player->vip()->notifyStatusChange(static_self_cast<Player>(), status, false);
		}
	}

	getParent()->postAddNotification(static_self_cast<Player>(), nullptr, 0);
	g_game().addCreatureCheck(static_self_cast<Player>());
	g_game().addPlayer(static_self_cast<Player>());
	static_self_cast<Player>()->onChangeZone(static_self_cast<Player>()->getZoneType());
	return true;
}

void Player::despawn() {
	if (isDead()) {
		return;
	}

	listWalkDir.clear();
	stopEventWalk();
	onWalkAborted();
	closeAllExternalContainers();
	g_game().playerSetAttackedCreature(static_self_cast<Player>()->getID(), 0);
	g_game().playerFollowCreature(static_self_cast<Player>()->getID(), 0);

	// remove check
	Game::removeCreatureCheck(static_self_cast<Player>());

	// remove from map
	const auto &tile = getTile();
	if (!tile) {
		return;
	}

	std::vector<int32_t> oldStackPosVector;

	const auto &spectators = Spectators().find<Creature>(tile->getPosition(), true);
	size_t i = 0;
	for (const auto &spectator : spectators) {
		if (const auto &player = spectator->getPlayer()) {
			oldStackPosVector.emplace_back(player->canSeeCreature(static_self_cast<Player>()) ? tile->getStackposOfCreature(player, getPlayer()) : -1);
		}
		if (const auto &player = spectator->getPlayer()) {
			player->sendRemoveTileThing(tile->getPosition(), oldStackPosVector[i++]);
		}

		spectator->onRemoveCreature(static_self_cast<Player>(), false);
	}

	tile->removeCreature(static_self_cast<Player>());

	getParent()->postRemoveNotification(static_self_cast<Player>(), nullptr, 0);

	g_game().removePlayer(static_self_cast<Player>());

	// show player as pending
	for (const auto &[key, player] : g_game().getPlayers()) {
		player->vip()->notifyStatusChange(static_self_cast<Player>(), VipStatus_t::PENDING, false);
	}

	if (g_configManager().getBoolean(LEAVE_PARTY_ON_DEATH) && m_party) {
		m_party->leaveParty(static_self_cast<Player>());
	}

	setDead(true);
}

bool Player::dropCorpse(const std::shared_ptr<Creature> &lastHitCreature, const std::shared_ptr<Creature> &mostDamageCreature, bool lastHitUnjustified, bool mostDamageUnjustified) {
	if (getZoneType() != ZONE_PVP || !Player::lastHitIsPlayer(lastHitCreature)) {
		return Creature::dropCorpse(lastHitCreature, mostDamageCreature, lastHitUnjustified, mostDamageUnjustified);
	}

	setDropLoot(true);
	return false;
}

std::shared_ptr<Item> Player::getCorpse(const std::shared_ptr<Creature> &lastHitCreature, const std::shared_ptr<Creature> &mostDamageCreature) {
	auto corpse = Creature::getCorpse(lastHitCreature, mostDamageCreature);
	if (!corpse || !corpse->getContainer()) {
		return nullptr;
	}

	std::ostringstream descriptionStream;
	std::string subjectPronoun = getSubjectPronoun();
	capitalizeWords(subjectPronoun);

	if (damageMap.empty()) {
		descriptionStream << fmt::format("You recognize {}.", getNameDescription());
	} else {
		descriptionStream << fmt::format("You recognize {}. {} was killed by ", getNameDescription(), subjectPronoun);

		// Only attackers of the fight that ended in this death count. damageMap is cleared only
		// when the player goes idle, so during a long hunt it still holds every creature that has
		// hit the player since the hunt began. Same in-fight window as Creature::onDeath.
		const int64_t timeNow = OTSYS_TIME();
		const uint32_t inFightTicks = g_configManager().getNumber(PZ_LOCKED);
		const auto isRecentAttacker = [timeNow, inFightTicks](const CountBlock_t &damageInfo) {
			return damageInfo.total > 0 && damageInfo.ticks > 0 && timeNow - damageInfo.ticks <= inFightTicks;
		};

		// The monster named is the one that landed the killing blow - the creature the death list
		// (player_deaths.killed_by) is derived from. damageMap is ordered by creature id, so taking
		// its first monster named whichever attacker had been alive the longest, e.g. a monster that
		// hit the player on the way into a hunting area instead of the one that killed them there.
		// Only when the last hit was not a monster of this fight (a player, an ownerless field) the
		// monster with the most damage in it is named.
		// Not the mostDamageCreature argument: Creature::onDeath has already replaced it with the
		// summon's master and, under shared experience, with the party leader.
		std::shared_ptr<Creature> killerMonster;
		if (lastHitCreature && lastHitCreature->isMonster()) {
			const auto it = damageMap.find(lastHitCreature->getID());
			if (it != damageMap.end() && isRecentAttacker(it->second)) {
				killerMonster = lastHitCreature;
			}
		}
		const bool killerIsLastHit = killerMonster != nullptr;
		int32_t killerMonsterDamage = 0;

		std::vector<std::string> killers;
		for (const auto &[creatureId, damageInfo] : damageMap) {
			if (creatureId == 0 || creatureId == getID() || !isRecentAttacker(damageInfo)) {
				continue;
			}

			const auto damageDealer = g_game().getCreatureByID(creatureId);
			if (!damageDealer) {
				continue;
			}

			if (damageDealer->isPlayer()) {
				killers.push_back(damageDealer->getNameDescription());
			} else if (!killerIsLastHit && damageDealer->isMonster() && damageInfo.total > killerMonsterDamage) {
				killerMonster = damageDealer;
				killerMonsterDamage = damageInfo.total;
			}
		}

		std::string monsterKiller;
		if (killerMonster) {
			const auto master = killerMonster->getMaster();
			if (master && master->isPlayer()) {
				monsterKiller = fmt::format("{} summoned by {}", killerMonster->getNameDescription(), master->getNameDescription());
			} else {
				monsterKiller = killerMonster->getNameDescription();
			}
		}

		if (!killers.empty()) {
			for (size_t i = 0; i < killers.size(); ++i) {
				if (i > 0) {
					descriptionStream << (i == killers.size() - 1 ? " and " : ", ");
				}
				descriptionStream << killers[i];
			}
			if (!monsterKiller.empty()) {
				descriptionStream << " and " << monsterKiller;
			}
		} else if (!monsterKiller.empty()) {
			descriptionStream << monsterKiller;
		} else {
			descriptionStream << "an unknown attacker";
		}

		descriptionStream << '.';
	}

	corpse->setAttribute(ItemAttribute_t::DESCRIPTION, descriptionStream.str());
	return corpse;
}

void Player::addInFightTicks(bool pzlock /*= false*/) {
	wheel()->checkAbilities();

	if (hasFlag(PlayerFlags_t::NotGainInFight)) {
		return;
	}

	if (pzlock) {
		pzLocked = true;
		sendIcons();
	}

	updateImbuementTrackerStats();

	safeCall([this] {
		addCondition(Condition::createCondition(CONDITIONID_DEFAULT, CONDITION_INFIGHT, g_configManager().getNumber(PZ_LOCKED)));
	});
}

