int32_t Player::getPerfectShotDamage(uint8_t range, bool useCharges) const {
	int32_t result = 0;
	auto it = perfectShot.find(range);
	if (it != perfectShot.end()) {
		result = it->second;
	}

	for (const auto &item : getEquippedItems()) {
		const ItemType &itemType = Item::items[item->getID()];
		if (!itemType.abilities) {
			continue;
		}

		if (!itemType.abilities->perfectShotRange) {
			continue;
		}

		if (itemType.abilities->perfectShotRange == range) {
			result += itemType.abilities->perfectShotDamage;
			const uint16_t charges = item->getCharges();
			if (useCharges && charges != 0) {
				g_game().transformItem(item, item->getID(), charges - 1);
			}
		}
	}

	auto it2 = equippedWeaponProficiency.gainDamageAtRange.find(range);
	if (it2 != equippedWeaponProficiency.gainDamageAtRange.end()) {
		result += static_cast<int32_t>(it2->second);
	}

	return result;
}

void Player::setPerfectShotDamage(uint8_t range, int32_t damage) {
	int32_t actualDamage = getPerfectShotDamage(range);
	const bool aboveZero = (actualDamage != 0);
	actualDamage += damage;
	if (actualDamage == 0 && aboveZero) {
		perfectShot.erase(range);
	} else {
		perfectShot[range] = actualDamage;
	}
}

int32_t Player::getSpecializedMagicLevel(CombatType_t combat, bool useCharges) const {
	int32_t result = specializedMagicLevel[combatTypeToIndex(combat)] + m_wheelPlayer->getSpecializedMagic(combat);
	for (const auto &item : getEquippedItems()) {
		const ItemType &itemType = Item::items[item->getID()];
		if (!itemType.abilities) {
			continue;
		}

		const int32_t specialized_magic_level = itemType.abilities->specializedMagicLevel[combatTypeToIndex(combat)];
		if (specialized_magic_level > 0) {
			result += specialized_magic_level;
			const uint16_t charges = item->getCharges();
			if (useCharges && charges != 0) {
				g_game().transformItem(item, item->getID(), charges - 1);
			}
		}
	}

	// Proficiency Perk: specialMagicLevel
	result += equippedWeaponProficiency.specialMagicLevel[combatTypeToIndex(combat)];

	// Vocation Adjustment: Paladin Divine Defiance grants 7.5% of distance fighting as bonus
	// holy AND healing magic level (one hook feeds both the native formula and the Lua callback).
	if (getStance() == STANCE_DIVINE_DEFIANCE && (combat == COMBAT_HOLYDAMAGE || combat == COMBAT_HEALING)) {
		result += static_cast<int32_t>(getSkillLevel(SKILL_DISTANCE) * 0.075);
	}

	// Vocation Adjustment: Druid Elemental Synthesis grants 10% of magic level as bonus ice
	// and earth magic level.
	if (getStance() == STANCE_ELEMENTAL_SYNTHESIS && (combat == COMBAT_ICEDAMAGE || combat == COMBAT_EARTHDAMAGE)) {
		result += static_cast<int32_t>(getMagicLevel() * 0.10);
	}

	return result;
}

void Player::setSpecializedMagicLevel(CombatType_t combat, int32_t value) {
	specializedMagicLevel[combatTypeToIndex(combat)] = std::max(0, specializedMagicLevel[combatTypeToIndex(combat)] + value);
