void Player::setGuild(const std::shared_ptr<Guild> &newGuild) {
	if (newGuild == guild) {
		return;
	}

	if (guild) {
		guild->removeMember(static_self_cast<Player>());
		guild = nullptr;
	}

	guildNick.clear();
	guildRank = nullptr;

	if (newGuild) {
		const auto &rank = newGuild->getRankByLevel(1);
		if (!rank) {
			return;
		}

		guild = newGuild;
		guildRank = rank;
		newGuild->addMember(static_self_cast<Player>());
	}
}

