bool Player::canSeeCreature(const std::shared_ptr<Creature> &creature) const {
	if (creature.get() == this) {
		return true;
	}

	if (creature->isInGhostMode() && !group->access) {
		return false;
	}

	if (!creature->getPlayer() && !canSeeInvisibility() && creature->isInvisible()) {
		return false;
	}
	return true;
}

bool Player::canWalkthrough(const std::shared_ptr<Creature> &creature) {
	if (group->access || creature->isInGhostMode()) {
		return true;
	}

	const auto &player = creature->getPlayer();
	const auto &monster = creature->getMonster();
	const auto &npc = creature->getNpc();
	bool noPvpThroughAtSummon = false;
	// Allow players to walk through summons in no pvp worlds
	if (g_game().getWorldType() == WORLD_TYPE_NO_PVP) {
		const auto &monsterMaster = monster ? monster->getMaster() : nullptr;
		const auto &monsterMasterPlayer = monsterMaster ? monsterMaster->getPlayer() : nullptr;
		if (monsterMasterPlayer) {
			noPvpThroughAtSummon = true;
		}
	}

	if (monster && (monster->isFamiliar() || noPvpThroughAtSummon)) {
		return true;
	}

	if (player) {
		const auto &playerTile = player->getTile();
		const bool legacyWalkthroughZone = playerTile && (playerTile->hasFlag(TILESTATE_NOPVPZONE) || playerTile->hasFlag(TILESTATE_PROTECTIONZONE) || player->getLevel() <= static_cast<uint32_t>(g_configManager().getNumber(PROTECTION_LEVEL)) || g_game().getWorldType() == WORLD_TYPE_NO_PVP);
		if (!playerTile) {
			return false;
		}

		if (!legacyWalkthroughZone && ExpertPvp::isEnabled()) {
			const auto relation = ExpertPvp::classifyRelation(player, getPlayer());
			const auto decision = ExpertPvp::canWalkThrough(relation.facts);
			if (decision.handled) {
				return decision.canWalkThrough;
			}
		}

		if (!legacyWalkthroughZone) {
			return false;
		}

		const auto &playerTileGround = playerTile->getGround();
		if (!playerTileGround || !playerTileGround->hasWalkStack()) {
			return false;
		}

		const auto &thisPlayer = getPlayer();
		if ((OTSYS_TIME() - lastWalkthroughAttempt) > 2000) {
			thisPlayer->setLastWalkthroughAttempt(OTSYS_TIME());
			return false;
		}

		if (creature->getPosition() != lastWalkthroughPosition) {
			thisPlayer->setLastWalkthroughPosition(creature->getPosition());
			return false;
		}

		thisPlayer->setLastWalkthroughPosition(creature->getPosition());
		return true;
	} else if (npc) {
		const auto &tile = npc->getTile();
		const auto &house = tile ? tile->getHouse() : nullptr;
		return (house != nullptr);
	}

	return false;
}

bool Player::canWalkthroughEx(const std::shared_ptr<Creature> &creature) const {
	if (group->access) {
		return true;
	}

	const auto &monster = creature->getMonster();
	if (monster) {
		if (!monster->isFamiliar()) {
			return false;
		}
		return true;
	}

	const auto &player = creature->getPlayer();
	const auto &npc = creature->getNpc();
	if (player) {
		const auto &playerTile = player->getTile();
		const bool legacyWalkthroughZone = playerTile && (playerTile->hasFlag(TILESTATE_NOPVPZONE) || playerTile->hasFlag(TILESTATE_PROTECTIONZONE) || player->getLevel() <= static_cast<uint32_t>(g_configManager().getNumber(PROTECTION_LEVEL)) || g_game().getWorldType() == WORLD_TYPE_NO_PVP);
		if (playerTile && !legacyWalkthroughZone && ExpertPvp::isEnabled()) {
			const auto relation = ExpertPvp::classifyRelation(player, getPlayer());
			const auto decision = ExpertPvp::canWalkThrough(relation.facts);
			if (decision.handled) {
				return decision.canWalkThrough;
			}
		}

		return legacyWalkthroughZone;
	} else if (npc) {
		const auto &tile = npc->getTile();
		const auto &houseTile = std::dynamic_pointer_cast<HouseTile>(tile);
		return (houseTile != nullptr);
	} else {
		return false;
	}
}

