void Player::setImmuneCleanse(ConditionType_t conditiontype) {
	if (conditiontype == CONDITION_FEARED) {
		setImmuneFear(11000);
	} else {
		for (auto &[type, time] : cleanseConditions) {
			if (type != conditiontype) {
				continue;
			}

			time = OTSYS_TIME() + 11000;
			return;
		}
		cleanseConditions.emplace_back(conditiontype, OTSYS_TIME() + 11000);
	}
}

bool Player::isImmuneCleanse(ConditionType_t conditiontype) const {
	const uint64_t timenow = OTSYS_TIME();
	if (conditiontype == CONDITION_FEARED) {
		return isImmuneFear();
	}

	for (const auto &[type, time] : cleanseConditions) {
		if (type != conditiontype || timenow > time) {
			continue;
		}

		return true;
	}

	return false;
}

void Player::setImmuneFear(uint32_t immuneTime /* = 10000 */) {
	m_fearCondition.first = CONDITION_FEARED;
	m_fearCondition.second = OTSYS_TIME() + immuneTime;
}

bool Player::isImmuneFear() const {
	const uint64_t timenow = OTSYS_TIME();
	return (m_fearCondition.first == CONDITION_FEARED) && (timenow <= m_fearCondition.second);
}

uint16_t Player::parseRacebyCharm(charmRune_t charmId, bool set /*= false*/, uint16_t newRaceid /*= 0*/) {
	uint16_t raceid = 0;
	switch (charmId) {
		case CHARM_WOUND:
		case CHARM_ENFLAME:
		case CHARM_POISON:
		case CHARM_FREEZE:
		case CHARM_ZAP:
		case CHARM_CURSE:
		case CHARM_CRIPPLE:
		case CHARM_PARRY:
		case CHARM_DODGE:
		case CHARM_ADRENALINE:
		case CHARM_NUMB:
		case CHARM_CLEANSE:
		case CHARM_BLESS:
		case CHARM_SCAVENGE:
		case CHARM_GUT:
		case CHARM_LOW:
		case CHARM_DIVINE:
		case CHARM_VAMP:
		case CHARM_VOID:
		case CHARM_SAVAGE:
		case CHARM_FATAL:
		case CHARM_VOIDINVERSION:
		case CHARM_CARNAGE:
		case CHARM_OVERPOWER:
		case CHARM_OVERFLUX:
			if (set) {
				charmsArray[charmId].raceId = newRaceid;
			} else {
				raceid = charmsArray[charmId].raceId;
			}
			break;
		default:
			raceid = 0;
			break;
	}
	return raceid;
}

bool Player::isNearDepotBox() const {
	const Position &pos = getPosition();
	for (int32_t cx = -1; cx <= 1; ++cx) {
		for (int32_t cy = -1; cy <= 1; ++cy) {
			const auto &posTile = g_game().map.getTile(static_cast<uint16_t>(pos.x + cx), static_cast<uint16_t>(pos.y + cy), pos.z);
			if (!posTile) {
				continue;
			}

			if (posTile->hasFlag(TILESTATE_DEPOT)) {
				return true;
			}
		}
	}
	return false;
}

std::shared_ptr<DepotChest> Player::getDepotChest(uint32_t depotId, bool autoCreate) {
	const auto it = depotChests.find(depotId);
	if (it != depotChests.end()) {
		return it->second;
	}

	if (!autoCreate) {
		return nullptr;
	}

	std::shared_ptr<DepotChest> depotChest;
	if (depotId > 0 && depotId < 18) {
		depotChest = std::make_shared<DepotChest>(ITEM_DEPOT_NULL + depotId);
	} else if (depotId == 18) {
		depotChest = std::make_shared<DepotChest>(ITEM_DEPOT_XVIII);
	} else if (depotId == 19) {
		depotChest = std::make_shared<DepotChest>(ITEM_DEPOT_XIX);
	} else {
		depotChest = std::make_shared<DepotChest>(ITEM_DEPOT_XX);
	}

	depotChests[depotId] = depotChest;
	return depotChest;
}

std::shared_ptr<DepotLocker> Player::getDepotLocker(uint32_t depotId) {
	const auto it = depotLockerMap.find(depotId);
	if (it != depotLockerMap.end()) {
		inbox->setParent(it->second);
		for (uint32_t i = g_configManager().getNumber(DEPOT_BOXES); i > 0; i--) {
			if (const auto &depotBox = getDepotChest(i, false)) {
				depotBox->setParent(it->second->getItemByIndex(0)->getContainer());
			}
		}
		return it->second;
	}

	// We need to make room for stash on 12+ protocol versions and remove it for 10x.
	const bool createStash = !client->oldProtocol;

	auto depotLocker = std::make_shared<DepotLocker>(ITEM_LOCKER, createStash ? 4 : 3);
	depotLocker->setDepotId(depotId);
	const auto &marketItem = Item::CreateItem(ITEM_MARKET);
	depotLocker->internalAddThing(marketItem);
	depotLocker->internalAddThing(inbox);
	if (createStash) {
		const auto &stashPtr = Item::CreateItem(ITEM_STASH);
		depotLocker->internalAddThing(stashPtr);
	}
	const auto &depotChest = Item::CreateItemAsContainer(ITEM_DEPOT, static_cast<uint16_t>(g_configManager().getNumber(DEPOT_BOXES)));
	for (uint32_t i = g_configManager().getNumber(DEPOT_BOXES); i > 0; i--) {
		const auto &depotBox = getDepotChest(i, true);
		depotChest->internalAddThing(depotBox);
		depotBox->setParent(depotChest);
	}
	depotLocker->internalAddThing(depotChest);
	depotLockerMap[depotId] = depotLocker;
	return depotLocker;
}

