	const auto [iterator, inserted] = attackedSet.emplace(attacked->guid);
	(void)iterator;
	if (inserted) {
		(void)attacked->attackerSet.emplace(guid);
	}
}

void Player::removeAttacked(const std::shared_ptr<Player> &attacked) {
	if (!attacked || attacked == getPlayer()) {
