void Player::onCreatureAppear(const std::shared_ptr<Creature> &creature, bool isLogin) {
	Creature::onCreatureAppear(creature, isLogin);

	if (isLogin && creature == getPlayer()) {
		onEquipInventory();

		// Refresh bosstiary tracker onLogin
		refreshCyclopediaMonsterTracker(true);
		// Refresh bestiary tracker onLogin
		refreshCyclopediaMonsterTracker(false);

		for (const auto &condition : storedConditionList) {
			addCondition(condition);
		}
		storedConditionList.clear();

		updateRegeneration();

		const auto &bed = g_game().getBedBySleeper(guid);
		if (bed) {
			bed->wakeUp(static_self_cast<Player>());
		}

		auto version = client && client->oldProtocol ? getProtocolVersion() : CLIENT_VERSION;
		const auto* protocolProfile = client ? client->getProtocolProfile() : nullptr;
		if (protocolProfile
		    && (protocolProfile->assetSignatures.dat != 0 || protocolProfile->assetSignatures.spr != 0 || protocolProfile->assetSignatures.pic != 0)) {
			g_logger().info(
				"{} has logged in. (Protocol: {}, Profile: {}, Assets: dat=0x{:08X} spr=0x{:08X} pic=0x{:08X})",
				name,
				version,
				protocolProfile->name,
				protocolProfile->assetSignatures.dat,
				protocolProfile->assetSignatures.spr,
				protocolProfile->assetSignatures.pic
			);
		} else if (protocolProfile) {
			g_logger().info("{} has logged in. (Protocol: {}, Profile: {})", name, version, protocolProfile->name);
		} else {
			g_logger().info("{} has logged in. (Protocol: {})", name, version);
		}

		std::string livestreamPassword;
		if (auto passwordValue = kv()->scoped("livestream-system")->get("password")) {
			livestreamPassword = passwordValue->get<std::string>();
		}

		std::string livestreamDescription;
		if (auto descriptionValue = kv()->scoped("livestream-system")->get("description")) {
			livestreamDescription = descriptionValue->get<std::string>();
		}

		uint32_t livestreamRecord = 0;
		if (auto recordValue = kv()->scoped("livestream-system")->get("live-record")) {
			const auto rawRecord = recordValue->getNumber();
			if (rawRecord > 0) {
				livestreamRecord = static_cast<uint32_t>(std::min<double>(rawRecord, std::numeric_limits<uint32_t>::max()));
			}
		}
		g_livestream().setInitialState(static_self_cast<Player>(), livestreamPassword, livestreamDescription, livestreamRecord);

		if (guild) {
			guild->addMember(static_self_cast<Player>());
		}

		int32_t offlineTime;
		if (getLastLogout() != 0) {
			// Not counting more than 21 days to prevent overflow when multiplying with 1000 (for milliseconds).
			offlineTime = std::min<int32_t>(time(nullptr) - getLastLogout(), 86400 * 21);
		} else {
			offlineTime = 0;
		}

		for (const auto &condition : getMuteConditions()) {
			condition->setTicks(condition->getTicks() - (offlineTime * 1000));
			if (condition->getTicks() <= 0) {
				removeCondition(condition);
			}
		}

		g_game().checkPlayersRecord();
		if (getLevel() < g_configManager().getNumber(ADVENTURERSBLESSING_LEVEL) && getVocationId() > VOCATION_NONE) {
			for (uint8_t i = 2; i <= 6; i++) {
				if (!hasBlessing(i)) {
					addBlessing(i, 1);
				}
			}
			sendBlessStatus();
		}

		if (getCurrentMount() != 0) {
			toggleMount(true);
		}

		g_game().changePlayerSpeed(static_self_cast<Player>(), 0);
	}
}

void Player::onRemoveCreature(const std::shared_ptr<Creature> &creature, bool isLogout) {
	Creature::onRemoveCreature(creature, isLogout);

	if (const auto &player = getPlayer(); player == creature) {
		if (isLogout) {
			onDeEquipInventory();

			if (m_party) {
				m_party->leaveParty(player, true);
			}
			if (guild) {
				guild->removeMember(player);
			}

			if (isDead()) {
				loginPosition = getTemplePosition();
			} else {
				loginPosition = getPosition();
			}
			lastLogout = time(nullptr);
			g_logger().info("{} has logged out", getName());
			g_chat().removeUserFromAllChannels(player);
			clearPartyInvitations();
		}

		if (eventWalk != 0) {
			setFollowCreature(nullptr);
		}

		if (tradePartner) {
			g_game().internalCloseTrade(player);
		}

		closeShopWindow();

		g_saveManager().savePlayer(player);
	}

	if (creature == shopOwner) {
		setShopOwner(nullptr);
		sendCloseShop();
	}
}

void Player::onCreatureMove(const std::shared_ptr<Creature> &creature, const std::shared_ptr<Tile> &newTile, const Position &newPos, const std::shared_ptr<Tile> &oldTile, const Position &oldPos, bool teleport) {
	Creature::onCreatureMove(creature, newTile, newPos, oldTile, oldPos, teleport);

	const auto &followCreature = getFollowCreature();
	if (hasFollowPath && (creature == followCreature || (creature.get() == this && followCreature))) {
		isUpdatingPath = false;
		updateCreatureWalk();
	}

	if (shopOwner && (creature == shopOwner || creature.get() == this) && !shopOwner->canInteract(getPosition()) && closeShopWindow()
	    && creature.get() != this) {
		return;
	}

	if (creature != getPlayer()) {
		return;
	}

	if (!teleport && oldPos.z == newPos.z) {
		updateParalyzeWalkExhaust();
	}

	if (tradeState != TRADE_TRANSFER) {
		// check if we should close trade
		if (tradeItem && !Position::areInRange<1, 1, 0>(tradeItem->getPosition(), getPosition())) {
			g_game().internalCloseTrade(getPlayer());
		}

		if (tradePartner && !Position::areInRange<2, 2, 0>(tradePartner->getPosition(), getPosition())) {
			g_game().internalCloseTrade(getPlayer());
		}
	}

	// close modal windows
	if (!modalWindows.empty()) {
		// TODO: This shouldn't be hardcoded
		for (const uint32_t modalWindowId : modalWindows) {
			if (modalWindowId == std::numeric_limits<uint32_t>::max()) {
				sendTextMessage(MESSAGE_EVENT_ADVANCE, "Offline training aborted.");
				break;
			}
		}
		modalWindows.clear();
	}

	// leave market
	if (inMarket) {
		inMarket = false;
	}

	if (m_party) {
		m_party->updateSharedExperience();
		m_party->updatePlayerStatus(getPlayer(), oldPos, newPos);
	}

	if (teleport || oldPos.z != newPos.z) {
		int32_t ticks = g_configManager().getNumber(STAIRHOP_DELAY);
		if (ticks > 0) {
			if (const auto &condition = Condition::createCondition(CONDITIONID_DEFAULT, CONDITION_PACIFIED, ticks, 0)) {
				addCondition(condition);
			}
		}
	}
}

void Player::onEquipInventory() {
	for (int32_t slot = CONST_SLOT_FIRST; slot <= CONST_SLOT_LAST; ++slot) {
		const auto &item = inventory[slot];
		if (item) {
			item->startDecaying();
			g_moveEvents().onPlayerEquip(getPlayer(), item, static_cast<Slots_t>(slot), false);
		}
	}
}

void Player::onDeEquipInventory() {
	for (int32_t slot = CONST_SLOT_FIRST; slot <= CONST_SLOT_LAST; ++slot) {
		const auto &item = inventory[slot];
		if (item) {
			if (g_moveEvents().onPlayerDeEquip(getPlayer(), item, static_cast<Slots_t>(slot)) == 0) {
				continue;
			}
		}
	}
}

