	std::shared_ptr<Player> getExpertPvpActorPlayer(const std::shared_ptr<Creature> &actor) {
		if (!actor) {
			return nullptr;
		}

		if (const auto &player = actor->getPlayer()) {
			return player;
		}

		const auto &master = actor->getMaster();
		return master ? master->getPlayer() : nullptr;
	}

	ExpertPvpActionKind getExpertPvpTargetActionKind(const CombatParams &params) {
		switch (params.origin) {
			case ORIGIN_MELEE:
			case ORIGIN_RANGED:
			case ORIGIN_FIST:
			case ORIGIN_WEAPON_PROFICIENCY:
				return ExpertPvpActionKind::DirectAttack;
			default:
				return ExpertPvpActionKind::RuneTarget;
		}
	}

	ReturnValue getExpertPvpTargetReturnValue(const ExpertPvpDecision &decision, const std::shared_ptr<Creature> &target) {
		if (!decision.handled || decision.allowed) {
			return RETURNVALUE_NOERROR;
		}

		return target && target->getPlayer() ? RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER : RETURNVALUE_YOUMAYNOTATTACKTHISCREATURE;
	}

	ReturnValue getExpertPvpCombatReturnValue(ExpertPvpActionKind actionKind, const std::shared_ptr<Creature> &actor, const std::shared_ptr<Creature> &target) {
		if (!target || !ExpertPvp::isEnabled() || !Combat::isPlayerCombat(target)) {
			return RETURNVALUE_NOERROR;
		}

		const auto actorPlayer = getExpertPvpActorPlayer(actor);
		if (!actorPlayer) {
			return RETURNVALUE_NOERROR;
		}

		const auto relation = ExpertPvp::classifyRelation(actorPlayer, target);
		const auto decision = ExpertPvp::evaluateCombatAction(actionKind, relation.facts);
		return getExpertPvpTargetReturnValue(decision, target);
	}

	void applyExpertPvpCombatSideEffects(ExpertPvpActionKind actionKind, const std::shared_ptr<Creature> &actor, const std::shared_ptr<Creature> &target) {
		if (!target || !ExpertPvp::isEnabled() || !Combat::isPlayerCombat(target)) {
			return;
		}

		const auto actorPlayer = getExpertPvpActorPlayer(actor);
		if (!actorPlayer) {
			return;
		}

		const auto relation = ExpertPvp::classifyRelation(actorPlayer, target);
		const auto decision = ExpertPvp::evaluateCombatAction(actionKind, relation.facts);
		ExpertPvp::applyCombatSideEffects(decision, relation.facts);
	}

	bool canDoCombatWithExpertPvp(const std::shared_ptr<Creature> &caster, const std::shared_ptr<Creature> &target, bool aggressive, ExpertPvpActionKind actionKind) {
		if (Combat::canDoCombat(caster, target, aggressive) != RETURNVALUE_NOERROR) {
			return false;
		}

		return getExpertPvpCombatReturnValue(actionKind, caster, target) == RETURNVALUE_NOERROR;
	}

	bool applyExpertPvpFieldDamage(const std::shared_ptr<MagicField> &field, const std::shared_ptr<Condition> &condition, const std::shared_ptr<Creature> &creature) {
		if (!field || !condition || !creature || !Combat::isPlayerCombat(creature) || !ExpertPvp::isEnabled()) {
			return false;
		}

		const auto fieldContext = ExpertPvp::getFieldContext(field);
		const auto relation = ExpertPvp::classifyFieldRelation(fieldContext, creature);
		const auto decision = ExpertPvp::evaluateFieldDamage(fieldContext, relation.facts);
		if (!decision.handled) {
			return false;
		}

		if (!decision.applyDamage) {
			return true;
		}

		const auto combatDecision = ExpertPvp::evaluateCombatAction(fieldContext.ownerMode, ExpertPvpActionKind::FieldDamage, relation.facts);
		ExpertPvp::applyCombatSideEffects(combatDecision, relation.facts);

		if (decision.setConditionOwner) {
			condition->setParam(CONDITION_PARAM_OWNER, decision.conditionOwnerGuid);
		}

		creature->addCondition(condition);
		return true;
	}
}

int32_t Combat::getLevelFormula(const std::shared_ptr<Player> &player, const std::shared_ptr<Spell> &wheelSpell, const CombatDamage &damage) const {
	if (!player) {
		return 0;
	}

	uint32_t magicLevelSkill = player->getMagicLevel();
	// Wheel of destiny - Runic Mastery
	if (player->wheel().getInstant("Runic Mastery") && wheelSpell && damage.instantSpellName.empty() && normal_random(0, 100) <= 25) {
		const auto conjuringSpell = g_spells().getInstantSpellByName(damage.runeSpellName);
		if (conjuringSpell && conjuringSpell != wheelSpell) {
			uint32_t castResult = conjuringSpell->canCast(player) ? 20 : 10;
			magicLevelSkill += magicLevelSkill * castResult / 100;
		}
	}

	int32_t levelFormula = player->getLevel() * 2 + (player->getMagicLevel() + player->getSpecializedMagicLevel(damage.primary.type, true)) * 3;
	return levelFormula;
}

CombatDamage Combat::getCombatDamage(const std::shared_ptr<Creature> &creature, const std::shared_ptr<Creature> &target) const {
	CombatDamage damage;
	damage.origin = params.origin;
	damage.primary.type = params.combatType;

	// If the caster is a player and their vocation is "Monk" (CipSoft style),
	// and the spell isn't a healing spell, try applying the elementalBond from the equipped weapon if it exists and is valid.
	const auto &casterPlayer = creature ? creature->getPlayer() : nullptr;
	if (casterPlayer && casterPlayer->getPlayerVocationEnum() == VOCATION_MONK_CIP && !instantSpellName.empty() && params.combatType != COMBAT_HEALING) {
		const auto &weapon = casterPlayer->getWeapon(true);
		if (weapon) {
			CombatType_t bond = Item::items[weapon->getID()].elementalBond;
			if (bond != COMBAT_NONE) {
				damage.primary.type = bond;
			} else {
				damage.primary.type = params.combatType;
			}
		} else {
			damage.primary.type = params.combatType;
		}
	}

	damage.instantSpellName = instantSpellName;
	damage.runeSpellName = runeSpellName;
	// Wheel of destiny
	const auto &wheelSpell = casterPlayer ? casterPlayer->wheel().getCombatDataSpell(damage) : nullptr;
	// End
	if (formulaType == COMBAT_FORMULA_DAMAGE) {
		damage.primary.value = normal_random(
			static_cast<int32_t>(mina),
			static_cast<int32_t>(maxa)
		);
	} else if (creature) {
		int32_t min, max;
		if (creature->getCombatValues(min, max)) {
			damage.primary.value = normal_random(min, max);
		} else if (const auto &player = creature->getPlayer()) {
			if (params.valueCallback) {
				params.valueCallback->getMinMaxValues(player, damage, params.useCharges);
			} else if (formulaType == COMBAT_FORMULA_LEVELMAGIC) {
				int32_t levelFormula = getLevelFormula(player, wheelSpell, damage);
				damage.primary.value = normal_random(
					static_cast<int32_t>(levelFormula * mina + minb),
					static_cast<int32_t>(levelFormula * maxa + maxb)
				);
			} else if (formulaType == COMBAT_FORMULA_SKILL) {
				const auto &tool = player->getWeapon();
				const WeaponShared_ptr &weapon = g_weapons().getWeapon(tool);
				if (weapon) {
					damage.primary.value = normal_random(
						static_cast<int32_t>(minb),
						static_cast<int32_t>(weapon->getWeaponDamage(player, target, tool, true) * maxa + maxb)
					);

					damage.secondary.type = weapon->getElementType();
					damage.secondary.value = weapon->getElementDamage(player, target, tool);
					if (params.useCharges) {
						auto charges = tool->getAttribute<uint16_t>(ItemAttribute_t::CHARGES);
						if (charges != 0) {
							g_game().transformItem(tool, tool->getID(), charges - 1);
						}
					}
				} else {
					damage.primary.value = normal_random(
						static_cast<int32_t>(minb),
						static_cast<int32_t>(maxb)
					);
				}
			}
		}
		if (casterPlayer && wheelSpell && wheelSpell->isInstant()) {
			wheelSpell->getCombatDataAugment(casterPlayer, damage);
			casterPlayer->weaponProficiency().applySpellAugment(damage, wheelSpell->getSpellId());
		}
	}

	return damage;
}

void Combat::getCombatArea(const Position &centerPos, const Position &targetPos, const std::unique_ptr<AreaCombat> &area, std::vector<std::shared_ptr<Tile>> &list) {
	if (targetPos.z >= MAP_MAX_LAYERS) {
		return;
	}

	if (area) {
		area->getList(centerPos, targetPos, list, getDirectionTo(targetPos, centerPos));
	} else {
		list.emplace_back(g_game().map.getOrCreateTile(targetPos));
	}
}

CombatType_t Combat::ConditionToDamageType(ConditionType_t type) {
	switch (type) {
		case CONDITION_FIRE:
			return COMBAT_FIREDAMAGE;

		case CONDITION_ENERGY:
			return COMBAT_ENERGYDAMAGE;

		case CONDITION_BLEEDING:
			return COMBAT_PHYSICALDAMAGE;

		case CONDITION_DROWN:
			return COMBAT_DROWNDAMAGE;

		case CONDITION_POISON:
			return COMBAT_EARTHDAMAGE;

		case CONDITION_FREEZING:
			return COMBAT_ICEDAMAGE;

		case CONDITION_DAZZLED:
			return COMBAT_HOLYDAMAGE;

		case CONDITION_CURSED:
			return COMBAT_DEATHDAMAGE;

		default:
			break;
	}

	return COMBAT_NONE;
}

ConditionType_t Combat::DamageToConditionType(CombatType_t type) {
	switch (type) {
		case COMBAT_FIREDAMAGE:
			return CONDITION_FIRE;

		case COMBAT_ENERGYDAMAGE:
			return CONDITION_ENERGY;

		case COMBAT_DROWNDAMAGE:
			return CONDITION_DROWN;

		case COMBAT_EARTHDAMAGE:
			return CONDITION_POISON;

		case COMBAT_ICEDAMAGE:
			return CONDITION_FREEZING;

		case COMBAT_HOLYDAMAGE:
			return CONDITION_DAZZLED;

		case COMBAT_DEATHDAMAGE:
			return CONDITION_CURSED;

		case COMBAT_PHYSICALDAMAGE:
			return CONDITION_BLEEDING;

		default:
			return CONDITION_NONE;
	}
}

bool Combat::isPlayerCombat(const std::shared_ptr<Creature> &target) {
	if (target->getPlayer()) {
		return true;
	}

	if (target->isSummon() && target->getMaster()->getPlayer()) {
		return true;
	}

	return false;
}

ReturnValue Combat::canTargetCreature(const std::shared_ptr<Player> &player, const std::shared_ptr<Creature> &target) {
	if (player == target) {
		return RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER;
	}

	if (!player->hasFlag(PlayerFlags_t::IgnoreProtectionZone)) {
		// pz-zone
		if (player->getZoneType() == ZONE_PROTECTION) {
			return RETURNVALUE_ACTIONNOTPERMITTEDINPROTECTIONZONE;
		}

		if (target->getZoneType() == ZONE_PROTECTION) {
			return RETURNVALUE_ACTIONNOTPERMITTEDINPROTECTIONZONE;
		}

		// nopvp-zone
		if (isPlayerCombat(target)) {
			if (player->getZoneType() == ZONE_NOPVP) {
				return RETURNVALUE_ACTIONNOTPERMITTEDINANOPVPZONE;
			}

			if (target->getZoneType() == ZONE_NOPVP) {
				return RETURNVALUE_YOUMAYNOTATTACKAPERSONINPROTECTIONZONE;
			}
		}
	}

	if (player->hasFlag(PlayerFlags_t::CannotUseCombat) || !target->isAttackable()) {
		if (target->getPlayer()) {
			return RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER;
		} else {
			return RETURNVALUE_YOUMAYNOTATTACKTHISCREATURE;
		}
	}

	if (target->getPlayer()) {
		if (isProtected(player, target->getPlayer())) {
			return RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER;
		}
	}

	const auto expertPvpRet = getExpertPvpCombatReturnValue(ExpertPvpActionKind::DirectAttack, player, target);
	if (expertPvpRet != RETURNVALUE_NOERROR) {
		return expertPvpRet;
	}

	if (target->getPlayer()) {
		if (!ExpertPvp::isEnabled() && player->hasSecureMode() && !Combat::isInPvpZone(player, target) && player->getSkullClient(target->getPlayer()) == SKULL_NONE) {
			return RETURNVALUE_TURNSECUREMODETOATTACKUNMARKEDPLAYERS;
		}
	}

	return canDoCombat(player, target, true);
}

ReturnValue Combat::canDoCombat(const std::shared_ptr<Creature> &caster, const std::shared_ptr<Tile> &tile, bool aggressive) {
	if (!aggressive || !tile) {
		return RETURNVALUE_NOERROR;
	}

	if (tile->hasProperty(CONST_PROP_BLOCKPROJECTILE)) {
		bool canThrow = false;

		if (const auto fieldList = tile->getItemList()) {
			for (const auto &findfield : *fieldList) {
				if (findfield && (findfield->getID() == ITEM_MAGICWALL || findfield->getID() == ITEM_MAGICWALL_SAFE)) {
					canThrow = true;
					break;
				}
			}
		}

		if (!canThrow) {
			return RETURNVALUE_CANNOTTHROW;
		}
	}

	if (aggressive && tile->hasFlag(TILESTATE_PROTECTIONZONE)) {
		return RETURNVALUE_ACTIONNOTPERMITTEDINPROTECTIONZONE;
	}

	if (tile->getTeleportItem()) {
		return RETURNVALUE_CANNOTTHROW;
	}

	if (caster) {
		const Position &casterPosition = caster->getPosition();
		const Position &tilePosition = tile->getPosition();
		if (casterPosition.z < tilePosition.z) {
			return RETURNVALUE_FIRSTGODOWNSTAIRS;
		} else if (casterPosition.z > tilePosition.z) {
			return RETURNVALUE_FIRSTGOUPSTAIRS;
		}

		if (const auto &player = caster->getPlayer()) {
			if (player->hasFlag(PlayerFlags_t::IgnoreProtectionZone)) {
				return RETURNVALUE_NOERROR;
			}
		}
	}
	ReturnValue ret = g_events().eventCreatureOnAreaCombat(caster, tile, aggressive);
	if (ret == RETURNVALUE_NOERROR) {
		ret = g_callbacks().dispatchReturnValue(EventCallback_t::creatureOnAreaCombat, caster, tile, aggressive);
	}
	return ret;
}

bool Combat::isInPvpZone(const std::shared_ptr<Creature> &attacker, const std::shared_ptr<Creature> &target) {
	return attacker->getZoneType() == ZONE_PVP && target->getZoneType() == ZONE_PVP;
}

bool Combat::isProtected(const std::shared_ptr<Player> &attacker, const std::shared_ptr<Player> &target) {
	uint32_t protectionLevel = g_configManager().getNumber(PROTECTION_LEVEL);
	if (target->getLevel() < protectionLevel || attacker->getLevel() < protectionLevel) {
		return true;
	}

	if ((!attacker->getVocation()->canCombat() || !target->getVocation()->canCombat()) && (attacker->getVocationId() == VOCATION_NONE || target->getVocationId() == VOCATION_NONE)) {
		return true;
	}

	if (attacker->getSkull() == SKULL_BLACK && attacker->getSkullClient(target) == SKULL_NONE) {
		return true;
	}

	return false;
}

ReturnValue Combat::canDoCombat(const std::shared_ptr<Creature> &attacker, const std::shared_ptr<Creature> &target, bool aggressive) {
	if (!aggressive) {
		return RETURNVALUE_NOERROR;
	}

	const auto &targetPlayer = target ? target->getPlayer() : nullptr;
	if (target) {
		const std::shared_ptr<Tile> &tile = target->getTile();
		if (tile->hasProperty(CONST_PROP_BLOCKPROJECTILE)) {
			return RETURNVALUE_NOTENOUGHROOM;
		}
		if (targetPlayer && tile->hasFlag(TILESTATE_PROTECTIONZONE)) {
			const auto permittedOnPz = targetPlayer->hasPermittedConditionInPZ();
			return permittedOnPz ? RETURNVALUE_NOERROR : RETURNVALUE_ACTIONNOTPERMITTEDINPROTECTIONZONE;
		}
	}

	if (attacker) {
		const auto &attackerMaster = attacker->getMaster();
		const auto &masterAttackerPlayer = attackerMaster ? attackerMaster->getPlayer() : nullptr;
		const auto &masterAttackerMonster = attackerMaster ? attackerMaster->getMonster() : nullptr;
		const auto &attackerPlayer = attacker->getPlayer();
		const auto &attackerMonster = attacker->getMonster();
		const auto &targetMonster = target ? target->getMonster() : nullptr;
		const auto &targetMaster = target ? target->getMaster() : nullptr;
		const auto &targetMasterPlayer = targetMaster ? targetMaster->getPlayer() : nullptr;
		if (targetPlayer) {
			if (targetPlayer->hasFlag(PlayerFlags_t::CannotBeAttacked)) {
				return RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER;
			}

			const auto &targetPlayerTile = targetPlayer->getTile();
			if (attackerPlayer) {
				if (attackerPlayer->hasFlag(PlayerFlags_t::CannotAttackPlayer)) {
					return RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER;
				}

				if (isProtected(attackerPlayer, targetPlayer)) {
					return RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER;
				}

				// nopvp-zone
				const auto &attackerTile = attackerPlayer->getTile();
				if (targetPlayerTile && targetPlayerTile->hasFlag(TILESTATE_NOPVPZONE)) {
					return RETURNVALUE_ACTIONNOTPERMITTEDINANOPVPZONE;
				} else if (attackerTile && attackerTile->hasFlag(TILESTATE_NOPVPZONE) && targetPlayerTile && !targetPlayerTile->hasFlag(TILESTATE_NOPVPZONE | TILESTATE_PROTECTIONZONE)) {
					return RETURNVALUE_ACTIONNOTPERMITTEDINANOPVPZONE;
				}

				if (attackerPlayer->getFaction() != FACTION_DEFAULT && attackerPlayer->getFaction() != FACTION_PLAYER && attackerPlayer->getFaction() == targetPlayer->getFaction()) {
					return RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER;
				}
			}

			if (attackerMaster) {
				if (masterAttackerPlayer) {
					if (masterAttackerPlayer->hasFlag(PlayerFlags_t::CannotAttackPlayer)) {
						return RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER;
					}

					if (targetPlayerTile && targetPlayerTile->hasFlag(TILESTATE_NOPVPZONE)) {
						return RETURNVALUE_ACTIONNOTPERMITTEDINANOPVPZONE;
					}

					if (isProtected(masterAttackerPlayer, targetPlayer)) {
						return RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER;
					}
				}
			}

			if (attackerMonster && (!attackerMaster || masterAttackerMonster)) {
				if (attacker->getFaction() != FACTION_DEFAULT && !attackerMonster->isEnemyFaction(targetPlayer->getFaction())) {
					return RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER;
				}
			}
		} else if (targetMonster) {
			const bool allowMonsterPerfTestFriendlyFire = attackerMonster && attacker != target
				&& !attacker->isSummon() && !target->isSummon()
				&& g_configManager().getBoolean(MONSTER_PERF_TEST_FRIENDLY_FIRE);
			if (!allowMonsterPerfTestFriendlyFire && attacker->getFaction() != FACTION_DEFAULT && attacker->getFaction() != FACTION_PLAYER && attackerMonster && !attackerMonster->isEnemyFaction(target->getFaction())) {
				return RETURNVALUE_YOUMAYNOTATTACKTHISCREATURE;
			}

			if (attackerPlayer) {
				if (attackerPlayer->hasFlag(PlayerFlags_t::CannotAttackMonster)) {
					return RETURNVALUE_YOUMAYNOTATTACKTHISCREATURE;
				}

				if (target->isSummon() && targetMasterPlayer && target->getZoneType() == ZONE_NOPVP) {
					return RETURNVALUE_ACTIONNOTPERMITTEDINANOPVPZONE;
				}
			} else if (attackerMonster && !allowMonsterPerfTestFriendlyFire) {
				if ((!targetMaster || !targetMasterPlayer) && attacker->getFaction() == FACTION_DEFAULT) {
					if (!attackerMaster || !masterAttackerPlayer) {
						return RETURNVALUE_YOUMAYNOTATTACKTHISCREATURE;
					}
				}
			}
		} else if (target && target->getNpc()) {
			return RETURNVALUE_YOUMAYNOTATTACKTHISCREATURE;
		}

		if (g_game().getWorldType() == WORLD_TYPE_NO_PVP) {
			if (attackerPlayer || masterAttackerPlayer) {
				if (targetPlayer) {
					if (!isInPvpZone(attacker, target)) {
						return RETURNVALUE_YOUMAYNOTATTACKTHISPLAYER;
					}
				}

				if (target && target->isSummon() && targetMasterPlayer) {
					if (!isInPvpZone(attacker, target)) {
						return RETURNVALUE_YOUMAYNOTATTACKTHISCREATURE;
					}
				}
			}
		}
	}
	ReturnValue ret = g_events().eventCreatureOnTargetCombat(attacker, target);
	if (ret == RETURNVALUE_NOERROR) {
		ret = g_callbacks().dispatchReturnValue(EventCallback_t::creatureOnTargetCombat, attacker, target);
	}
	return ret;
}

